  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay1_PS_3_out1 <= to_unsigned(16#00#, 8);
      ELSIF enb = '1' THEN
        Delay1_PS_3_out1 <= Switch_out1_1;
      END IF;
    END IF;
  END PROCESS Delay1_PS_3_process;


  Delay1_PS_4_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay1_PS_4_out1 <= to_unsigned(16#00#, 8);
      ELSIF enb = '1' THEN
        Delay1_PS_4_out1 <= Delay1_PS_3_out1;
      END IF;
    END IF;
  END PROCESS Delay1_PS_4_process;


  Constant_out1_1 <= to_unsigned(16#3FE#, 11);

  Subtract_add_temp <= resize(Delay1_PS_4_out1, 12) + resize(Constant_out1_1, 12);
  Subtract_out1 <= signed(Subtract_add_temp);

  Data_Type_Conversion_out1 <= unsigned(Subtract_out1(10 DOWNTO 0));

  Delay3_PS_5_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay3_PS_5_out1 <= to_unsigned(16#000#, 11);
      ELSIF enb = '1' THEN
        Delay3_PS_5_out1 <= Data_Type_Conversion_out1;
      END IF;
    END IF;
  END PROCESS Delay3_PS_5_process;


  Constant_out1_2 <= to_unsigned(16#000#, 11);

  
  Switch1_out1_1 <= Delay3_PS_5_out1 WHEN Delay5_PS_2_5_out1 = '0' ELSE
      Constant_out1_2;

  Constant5_out1_1 <= to_unsigned(16#000#, 11);

  
  Switch5_out1 <= Switch1_out1_1 WHEN Delay1_out1 = '0' ELSE
      Constant5_out1_1;

  Delay1_PS_6_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay1_PS_6_out1 <= to_unsigned(16#000#, 11);
      ELSIF enb = '1' THEN
        Delay1_PS_6_out1 <= Switch5_out1;
      END IF;
    END IF;
  END PROCESS Delay1_PS_6_process;


  Constant_out1_3 <= to_unsigned(16#10#, 8);

  Subtract_sub_cast <= signed(resize(Constant_out1_3, 9));
  Subtract_sub_cast_1 <= signed(resize(Delay1_PS_3_out1, 9));
  Subtract_out1_1 <= Subtract_sub_cast - Subtract_sub_cast_1;

  Delay1_PS_4_1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay1_PS_4_out1_1 <= to_signed(16#000#, 9);
      ELSIF enb = '1' THEN
        Delay1_PS_4_out1_1 <= Subtract_out1_1;
      END IF;
    END IF;
  END PROCESS Delay1_PS_4_1_process;


  shift_arithmetic_zerosig <= to_signed(16#000#, 9);

  
  shift_arithmetic_selsig <= Delay1_PS_4_out1_1 WHEN Delay1_PS_4_out1_1 >= shift_arithmetic_zerosig ELSE
      shift_arithmetic_zerosig;

  reduced_2_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        reduced_reg(0) <= to_unsigned(16#0000#, 16);
        reduced_reg(1) <= to_unsigned(16#0000#, 16);
      ELSIF enb = '1' THEN
        reduced_reg(0) <= reduced_reg_next(0);
        reduced_reg(1) <= reduced_reg_next(1);
      END IF;
    END IF;
  END PROCESS reduced_2_process;

  Data_Type_Conversion2_out1_1 <= reduced_reg(1);
  reduced_reg_next(0) <= Data_Type_Conversion2_out1;
  reduced_reg_next(1) <= reduced_reg(0);

  shift_arithmetic_zerosig_1 <= to_signed(16#000#, 9);

  
  shift_arithmetic_selsig_1 <= shift_arithmetic_selsig WHEN shift_arithmetic_selsig >= shift_arithmetic_zerosig_1 ELSE
      shift_arithmetic_zerosig_1;

  Shift_Arithmetic_out1 <= Data_Type_Conversion2_out1_1 sll to_integer(shift_arithmetic_selsig_1);

  Delay3_PS_5_1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay3_PS_5_out1_1 <= to_unsigned(16#0000#, 16);
      ELSIF enb = '1' THEN
        Delay3_PS_5_out1_1 <= Shift_Arithmetic_out1;
      END IF;
    END IF;
  END PROCESS Delay3_PS_5_1_process;


  Bit_Slice1_out1_2 <= Delay3_PS_5_out1_1(14 DOWNTO 0);

  Constant_out1_4 <= to_unsigned(0, 37);

  Bit_Concat_out1 <= Bit_Slice1_out1_2 & Constant_out1_4;

  Constant1_out1_1 <= to_unsigned(0, 52);

  
  Switch2_out1_1 <= Bit_Concat_out1 WHEN Delay5_PS_2_5_out1 = '0' ELSE
      Constant1_out1_1;

  Constant6_out1_1 <= to_unsigned(0, 52);

  
  Switch6_out1_1 <= Switch2_out1_1 WHEN Delay1_out1 = '0' ELSE
      Constant6_out1_1;

  Delay3_PS_6_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        Delay3_PS_6_out1 <= to_unsigned(0, 52);
      ELSIF enb = '1' THEN
        Delay3_PS_6_out1 <= Switch6_out1_1;
      END IF;
    END IF;
  END PROCESS Delay3_PS_6_process;


  -- Combine FP sign, exponent, mantissa into 64 bit word
  nfp_out_pack <= Delay2_PS_6_out1 & Delay1_PS_6_out1 & Delay3_PS_6_out1;

  nfp_out <= std_logic_vector(nfp_out_pack);

END rtl;

